//! Recovering a character from the SHAPE of a glyph.
//!
//! Last resort of the extraction ladder (ADR-0005): when a glyph has no
//! ToUnicode entry, no reverse `cmap` entry and no GSUB evidence — which is the
//! normal state of a subset font whose layout tables were stripped — its outline
//! is still the letter a human reads. We describe the outline with a small,
//! typeface-independent signature and compare it with prototypes built from the
//! bundled OFL faces in their four joining forms.
//!
//! The prototype table is generated by `cargo run --example build_shapes` and
//! embedded as a compact blob (24 bytes per record), so nothing has to carry
//! font files at runtime.

/// Joining form of an Arabic letter.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Form {
    Isolated,
    Initial,
    Medial,
    Final,
}

impl Form {
    fn from_u8(v: u8) -> Form {
        match v {
            1 => Form::Initial,
            2 => Form::Medial,
            3 => Form::Final,
            _ => Form::Isolated,
        }
    }
    pub fn as_u8(self) -> u8 {
        match self {
            Form::Isolated => 0,
            Form::Initial => 1,
            Form::Medial => 2,
            Form::Final => 3,
        }
    }
}

/// A typeface-independent signature of one glyph outline.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Descriptor {
    /// Fraction of outline samples in each cell of a `GRID`×`GRID` grid over the
    /// glyph's own bounding box (so the signature is scale and position independent).
    pub grid: [f32; CELLS],
    /// Width / height of the bounding box, clamped to 4.0.
    pub aspect: f32,
    /// How far the glyph descends below the baseline, as a fraction of its height.
    pub descend: f32,
    /// The dot marks above the body and below it: their combined area relative to
    /// the body, and the aspect of the box they occupy. Arabic letters that share
    /// a skeleton are told apart by exactly this (ب ت ث ن ي, ج ح خ, د ذ, ر ز …).
    /// Fonts merge adjacent dots into one contour, so counting contours does not
    /// work; area and spread do. Which SIDE carries marks is matched as a category.
    pub marks_above: MarkCluster,
    pub marks_below: MarkCluster,
}

/// Dot marks on one side of a letter's body.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct MarkCluster {
    /// Combined area of the marks, relative to the body's area.
    pub area: f32,
    /// Width / height of the box the marks occupy (1 dot ≈ 1, a row of 2 ≈ 2).
    pub aspect: f32,
}

impl MarkCluster {
    fn present(&self) -> bool {
        self.area > 0.0
    }
    fn distance(&self, other: &MarkCluster) -> f32 {
        if self.present() != other.present() {
            return 1.0; // a letter with dots is never the same letter as one without
        }
        if !self.present() {
            return 0.0;
        }
        (self.area - other.area).abs().min(0.5) * 1.6
            + (self.aspect - other.aspect).abs().min(2.0) * 0.12
    }
}

/// Accumulates outline samples into a [`Descriptor`].
#[derive(Default, Debug, Clone)]
pub struct ShapeSampler {
    points: Vec<(f32, f32)>,
    /// Index into `points` where each contour starts, so small closed contours
    /// (the dots) can be told from the body.
    contour_starts: Vec<usize>,
    last: Option<(f32, f32)>,
}

impl ShapeSampler {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn is_empty(&self) -> bool {
        self.points.len() < 3
    }

    pub fn move_to(&mut self, x: f32, y: f32) {
        self.contour_starts.push(self.points.len());
        self.points.push((x, y));
        self.last = Some((x, y));
    }

    pub fn line_to(&mut self, x: f32, y: f32) {
        // sample along the segment so long strokes weigh as much as they look
        if let Some((px, py)) = self.last {
            for i in 1..=4 {
                let t = i as f32 / 4.0;
                self.points.push((px + (x - px) * t, py + (y - py) * t));
            }
        } else {
            self.points.push((x, y));
        }
        self.last = Some((x, y));
    }

    pub fn quad_to(&mut self, cx: f32, cy: f32, x: f32, y: f32) {
        let (px, py) = self.last.unwrap_or((cx, cy));
        for i in 1..=6 {
            let t = i as f32 / 6.0;
            let u = 1.0 - t;
            self.points.push((
                u * u * px + 2.0 * u * t * cx + t * t * x,
                u * u * py + 2.0 * u * t * cy + t * t * y,
            ));
        }
        self.last = Some((x, y));
    }

    pub fn curve_to(&mut self, c1x: f32, c1y: f32, c2x: f32, c2y: f32, x: f32, y: f32) {
        let (px, py) = self.last.unwrap_or((c1x, c1y));
        for i in 1..=8 {
            let t = i as f32 / 8.0;
            let u = 1.0 - t;
            let (u2, t2) = (u * u, t * t);
            self.points.push((
                u2 * u * px + 3.0 * u2 * t * c1x + 3.0 * u * t2 * c2x + t2 * t * x,
                u2 * u * py + 3.0 * u2 * t * c1y + 3.0 * u * t2 * c2y + t2 * t * y,
            ));
        }
        self.last = Some((x, y));
    }

    /// Finish the signature. `units_per_em` puts the descender on a common scale;
    /// pass the font's upem for outlines, or the drawn size for Type3 procedures.
    pub fn finish(&self, units_per_em: f32) -> Option<Descriptor> {
        if self.is_empty() {
            return None;
        }
        let bbox = |pts: &[(f32, f32)]| -> (f32, f32, f32, f32) {
            let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
            for (x, y) in pts {
                x0 = x0.min(*x);
                y0 = y0.min(*y);
                x1 = x1.max(*x);
                y1 = y1.max(*y);
            }
            (x0, y0, x1, y1)
        };
        let (x0, y0, x1, y1) = bbox(&self.points);
        let (w, h) = (x1 - x0, y1 - y0);
        if w <= f32::EPSILON || h <= f32::EPSILON {
            return None;
        }
        // Split contours into the body (the largest) and the dot marks around it.
        let mut contours: Vec<(f32, f32, f32, f32)> = vec![];
        for (i, start) in self.contour_starts.iter().enumerate() {
            let end = self
                .contour_starts
                .get(i + 1)
                .copied()
                .unwrap_or(self.points.len());
            if end > *start + 2 {
                contours.push(bbox(&self.points[*start..end]));
            }
        }
        let area_of = |c: &(f32, f32, f32, f32)| (c.2 - c.0) * (c.3 - c.1);
        let glyph_area = w * h;
        let body = contours
            .iter()
            .copied()
            .max_by(|a, b| area_of(a).partial_cmp(&area_of(b)).unwrap())
            .unwrap_or((x0, y0, x1, y1));
        let body_area = area_of(&body).max(1.0);
        let body_mid = (body.1 + body.3) / 2.0;
        let mut sides: [Vec<(f32, f32, f32, f32)>; 2] = [vec![], vec![]]; // [above, below]
        for c in &contours {
            if std::ptr::eq(c, &body) || area_of(c) > 0.15 * glyph_area {
                continue;
            }
            let mid = (c.1 + c.3) / 2.0;
            sides[usize::from(mid <= body_mid)].push(*c);
        }
        let cluster = |v: &Vec<(f32, f32, f32, f32)>| -> MarkCluster {
            if v.is_empty() {
                return MarkCluster::default();
            }
            let area: f32 = v.iter().map(area_of).sum::<f32>() / body_area;
            let (mut mx0, mut my0, mut mx1, mut my1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
            for (a, b, c, d) in v {
                mx0 = mx0.min(*a);
                my0 = my0.min(*b);
                mx1 = mx1.max(*c);
                my1 = my1.max(*d);
            }
            let (mw, mh) = ((mx1 - mx0).max(1.0), (my1 - my0).max(1.0));
            MarkCluster {
                area: area.min(0.5),
                aspect: (mw / mh).min(4.0),
            }
        };
        let (marks_above, marks_below) = (cluster(&sides[0]), cluster(&sides[1]));
        let mut grid = [0f32; CELLS];
        for (x, y) in &self.points {
            let cx = (((x - x0) / w) * GRID as f32).min(GRID as f32 - 0.001) as usize;
            // grid row 0 is the TOP of the glyph, so invert y (which grows upwards)
            let cy = ((1.0 - (y - y0) / h) * GRID as f32).min(GRID as f32 - 0.001) as usize;
            grid[cy * GRID + cx] += 1.0;
        }
        let total = self.points.len() as f32;
        for v in grid.iter_mut() {
            *v /= total;
        }
        // how far the glyph reaches below the baseline (y = 0), as a fraction of its height
        let descend = if units_per_em > 0.0 {
            ((-y0).max(0.0) / h).min(1.0)
        } else {
            0.0
        };
        Some(Descriptor {
            grid,
            aspect: (w / h).min(4.0),
            descend,
            marks_above,
            marks_below,
        })
    }
}

impl Descriptor {
    /// Distance to another signature. Lower is more alike; below ~0.12 is a good match.
    ///
    /// A different dot pattern means a different letter, so it is priced far
    /// above any shape difference rather than being averaged in.
    pub fn distance(&self, other: &Descriptor) -> f32 {
        let grid: f32 = self
            .grid
            .iter()
            .zip(other.grid.iter())
            .map(|(a, b)| (a - b) * (a - b))
            .sum::<f32>()
            .sqrt();
        let aspect = (self.aspect - other.aspect).abs() / 4.0;
        let descend = (self.descend - other.descend).abs();
        let marks = self.marks_above.distance(&other.marks_above)
            + self.marks_below.distance(&other.marks_below);
        grid + 0.35 * aspect + 0.25 * descend + marks
    }

    fn to_record(self, ch: char, form: Form, font: u8) -> [u8; RECORD] {
        let mut r = [0u8; RECORD];
        r[..4].copy_from_slice(&(ch as u32).to_le_bytes());
        r[4] = form.as_u8();
        r[5] = font;
        r[6] = ((self.aspect / 4.0) * 255.0).round().clamp(0.0, 255.0) as u8;
        r[7] = (self.descend * 255.0).round().clamp(0.0, 255.0) as u8;
        let q = |v: f32, scale: f32| ((v / scale) * 255.0).round().clamp(0.0, 255.0) as u8;
        r[8 + CELLS] = q(self.marks_above.area, 0.5);
        r[9 + CELLS] = q(self.marks_above.aspect, 4.0);
        r[10 + CELLS] = q(self.marks_below.area, 0.5);
        r[11 + CELLS] = q(self.marks_below.aspect, 4.0);
        for (i, v) in self.grid.iter().enumerate() {
            // grid values are fractions of the sample count; 0.25 is already a very dense cell
            r[8 + i] = ((v / 0.25) * 255.0).round().clamp(0.0, 255.0) as u8;
        }
        r
    }

    fn from_record(r: &[u8]) -> (char, Form, Descriptor) {
        let ch = char::from_u32(u32::from_le_bytes([r[0], r[1], r[2], r[3]])).unwrap_or('\u{FFFD}');
        let form = Form::from_u8(r[4]);
        let mut grid = [0f32; CELLS];
        for i in 0..16 {
            grid[i] = (r[8 + i] as f32 / 255.0) * 0.25;
        }
        (
            ch,
            form,
            Descriptor {
                grid,
                aspect: (r[6] as f32 / 255.0) * 4.0,
                descend: r[7] as f32 / 255.0,
                marks_above: MarkCluster {
                    area: (r[8 + CELLS] as f32 / 255.0) * 0.5,
                    aspect: (r[9 + CELLS] as f32 / 255.0) * 4.0,
                },
                marks_below: MarkCluster {
                    area: (r[10 + CELLS] as f32 / 255.0) * 0.5,
                    aspect: (r[11 + CELLS] as f32 / 255.0) * 4.0,
                },
            },
        )
    }
}

/// Cells per axis of the zoning grid.
/// 4 measured better than 6: a finer grid starts describing the typeface
/// rather than the letter, and precision on held-out fonts drops sharply.
pub const GRID: usize = 4;
pub const CELLS: usize = GRID * GRID;
const RECORD: usize = 8 + CELLS + 4;

/// Prototypes generated from the bundled OFL faces (`cargo run --example build_shapes`).
static PROTOTYPES: &[u8] = include_bytes!("shape_prototypes.bin");

/// Serialize prototypes for the generator.
pub fn encode_prototypes(items: &[(char, Form, u8, Descriptor)]) -> Vec<u8> {
    items
        .iter()
        .flat_map(|(c, f, font, d)| d.to_record(*c, *f, *font))
        .collect()
}

/// Largest distance still accepted as a match.
///
/// Measured on fonts that contributed no prototypes (IBM Plex Sans Arabic, Noto
/// Sans Arabic, Amiri Bold): at this threshold every answer was correct, while a
/// looser one started returning wrong letters. Recovering a character wrongly is
/// worse than leaving a placeholder, so this is tuned for precision, not recall.
pub const MAX_DISTANCE: f32 = 0.11;

/// Best matching character for a glyph signature, with its distance.
///
/// `max_distance` rejects everything that is not clearly a letter; callers
/// should treat a rejection as "unknown" rather than guessing.
pub fn best_match(d: &Descriptor, max_distance: f32) -> Option<(char, Form, f32)> {
    // A glyph with no dots is the ambiguous case: fonts that build dotted letters
    // from a skeleton plus separate dot glyphs (Noto Naskh among them) present a
    // bare skeleton that genuinely resembles several undotted letters. Hold those
    // to a tighter bar so a skeleton is left unknown rather than guessed at.
    let max_distance = if d.marks_above.present() || d.marks_below.present() {
        max_distance
    } else {
        max_distance * 0.7
    };
    let mut best: Option<(char, Form, f32)> = None;
    for r in PROTOTYPES.as_chunks::<RECORD>().0 {
        let (ch, form, proto) = Descriptor::from_record(r);
        let dist = d.distance(&proto);
        if best.map(|(_, _, b)| dist < b).unwrap_or(true) {
            best = Some((ch, form, dist));
        }
    }
    best.filter(|(_, _, dist)| *dist <= max_distance)
}

/// Number of prototypes available (0 when the table has not been generated).
pub fn prototype_count() -> usize {
    PROTOTYPES.len() / RECORD
}

#[cfg(test)]
mod tests {
    use super::*;

    fn square() -> Descriptor {
        let mut s = ShapeSampler::new();
        s.move_to(0.0, 0.0);
        s.line_to(100.0, 0.0);
        s.line_to(100.0, 100.0);
        s.line_to(0.0, 100.0);
        s.line_to(0.0, 0.0);
        s.finish(1000.0).unwrap()
    }

    #[test]
    fn a_signature_is_scale_and_position_independent() {
        let mut big = ShapeSampler::new();
        big.move_to(500.0, 500.0);
        big.line_to(900.0, 500.0);
        big.line_to(900.0, 900.0);
        big.line_to(500.0, 900.0);
        big.line_to(500.0, 500.0);
        let a = square();
        let b = big.finish(1000.0).unwrap();
        assert!(
            a.distance(&b) < 0.02,
            "same shape at another scale: {}",
            a.distance(&b)
        );
    }

    #[test]
    fn different_shapes_are_far_apart() {
        let mut wide = ShapeSampler::new();
        wide.move_to(0.0, 0.0);
        wide.line_to(400.0, 0.0);
        wide.line_to(400.0, 40.0);
        wide.line_to(0.0, 40.0);
        wide.line_to(0.0, 0.0);
        assert!(square().distance(&wide.finish(1000.0).unwrap()) > 0.1);
    }

    #[test]
    fn a_record_survives_the_round_trip() {
        let d = square();
        let bytes = encode_prototypes(&[('ب', Form::Initial, 0, d)]);
        assert_eq!(bytes.len(), RECORD);
        let (ch, form, back) = Descriptor::from_record(&bytes);
        assert_eq!((ch, form), ('ب', Form::Initial));
        assert!(
            d.distance(&back) < 0.02,
            "quantization lost too much: {}",
            d.distance(&back)
        );
    }

    #[test]
    fn the_generated_prototype_table_is_present_and_matches_itself() {
        assert!(
            prototype_count() > 100,
            "prototype table looks empty: {}",
            prototype_count()
        );
        // every prototype must be its own best match
        let mut exact = 0;
        for r in PROTOTYPES.as_chunks::<RECORD>().0.iter().step_by(7) {
            let (ch, _, d) = Descriptor::from_record(r);
            if let Some((got, _, dist)) = best_match(&d, 1.0) {
                if got == ch || dist < 0.02 {
                    exact += 1;
                }
            }
        }
        assert!(exact > 0, "prototypes do not match themselves");
    }
}
